package ca.yorku.eecs3311.coursepilot.application.agent; import ca.yorku.eecs3311.coursepilot.application.dto.DocumentResponse; import ca.yorku.eecs3311.coursepilot.application.service.*; import org.springframework.stereotype.Component; import java.time.LocalDate; import java.util.*; @Component public class AgentToolManager {private final ProgressService progress;private final LearningHistoryService history;private final RecommendationService recommendation;private final CourseMaterialService materials;private final CourseSearchService search;private final FlashcardGenerationService flashcards;private final QuizGenerationService quizzes;private final SummarizationService summaries;private final StudyPlanService studyPlans;public AgentToolManager(ProgressService p,LearningHistoryService h,RecommendationService r,CourseMaterialService m,CourseSearchService cs,FlashcardGenerationService f,QuizGenerationService q,SummarizationService s,StudyPlanService sp){progress=p;history=h;recommendation=r;materials=m;search=cs;flashcards=f;quizzes=q;summaries=s;studyPlans=sp;}public AgentTool.ToolResult execute(AgentPlanStep step,Long courseId){try{return switch(step.tool()){case "COURSE_SEARCH"->ok(step,search.search(courseId,step.parameters().getOrDefault("query",""),5).toString());case "GET_PROGRESS"->ok(step,progress.summarize(courseId).toString());case "GET_WEAK_TOPICS"->ok(step,progress.summarize(courseId).topics().stream().filter(t->!t.status().equals("STRONG")).toList().toString());case "GET_HISTORY"->ok(step,history.recent(courseId,10).toString());case "GET_RECOMMENDATION"->ok(step,recommendation.recommend(courseId).toString());case "GET_STUDY_PLAN"->ok(step,studyPlans.list(courseId).toString());case "GENERATE_SUMMARY"->ok(step,summaries.summarizeDocument(courseId,readyDocument(courseId).id()).toString());case "GENERATE_FLASHCARDS"->ok(step,flashcards.generate(courseId,readyDocument(courseId).id(),5).toString());case "GENERATE_QUIZ"->ok(step,quizzes.generate(courseId,readyDocument(courseId).id(),5,Set.of()).toString());case "CREATE_STUDY_PLAN"->ok(step,studyPlans.create(courseId,LocalDate.now(),LocalDate.now().plusDays(6),60,"WEAK_TOPIC_FOCUSED").toString());default->new AgentTool.ToolResult(step.tool(),false,"Unsupported tool.");};}catch(RuntimeException e){return new AgentTool.ToolResult(step.tool(),false,"Tool failed safely: "+Objects.toString(e.getMessage(),"unknown error"));}}private AgentTool.ToolResult ok(AgentPlanStep step,String output){return new AgentTool.ToolResult(step.tool(),true,output);}private DocumentResponse readyDocument(Long courseId){return materials.listDocuments(courseId).stream().filter(d->"READY".equals(d.processingStatus())).findFirst().orElseThrow(()->new IllegalArgumentException("No ready course material is available."));}}
